style.css:
@-moz-document domain("itch.io") {
:root { color-scheme: dark !important; }

  /* ==== Base surfaces (apex chrome pages only; creator layouts excluded) ==== */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
    /* itch's three MUTED-TEXT tokens are tuned for its white page (#606060 / #767676 /
       #858585) and land at 2.5–4.4:1 on ours. They are referenced ~500 times across post
       dates, edit notes, breadcrumbs, facet counts, blog metadata and moderation notices —
       chasing them selector-by-selector is what every previous patrol did and each one found
       more. Rebinding the tokens on the apex body fixes the whole family at once; creator
       layouts are excluded by the prefix so their own values are untouched. Only these three
       are safe: --itchio_body_color and _med are also painted as SURFACES (the hamburger
       bars, the WEB flag) and are handled by their own rules. */
    --itchio_body_color_light: #8b949e;
    --itchio_body_color_lighter: #8b949e;
    --itchio_body_color_gray: #8b949e;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .main_column,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .index_sidebar,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .anon_intro,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .community_topic_page,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .community_page_page,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .inner_column,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .wrapper.main {
    background-color: transparent !important;
  }
  /* On mobile the hamburger flips .index_sidebar to .visible — a position:fixed full-screen
     menu that ships opaque #f4f4f4; the transparent rule above would let content bleed
     through it, so re-establish an opaque dark surface for the open overlay. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .index_sidebar.visible {
    background-color: #14181d !important;
  }

  /* Soften light default borders to subtle dark (apex chrome only) */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) * {
    border-color: #262c33 !important;
  }

  /* ==== Headings / body text ==== */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) h1,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) h2,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) h3,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) h4,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .title,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .game_title,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .game_title a {
    color: #e6edf3 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .game_author,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .game_text,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .post_content,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .content_frame {
    color: #c4cdd6 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .game_genre,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .post_author,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .section_description,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .meta_row,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .game_meta_data,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .date,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .game_platform,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_group_label,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .group_toggle_btn,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_arrow,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .toggle_more_btn,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_label,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .clear_filters,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .clear_filters_link,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_clear,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .secondary_text {
    color: #8b949e !important;
  }
  /* Little circular "clear this filter" disc ships light grey (#dbdbdb) */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_clear > .svgicon {
    background-color: #30363d !important;
  }

  /* ==== Links / accent (itch brand red-pink, adapted for dark) ==== */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) a {
    color: #fa7d8c !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) a:hover {
    color: #ffa2ad !important;
  }
  /* Links that ARE a filled pill keep itch's own background, so the blanket accent above puts
     accent-on-accent: the devlog post-type badge drops 5.25:1 -> 2.09:1, and the keyboard
     skip link 3.75:1 -> 1.5:1 on itch red. Both are natively white — restore that. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .post_type a,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) a.skip_to_main {
    color: #ffffff !important;
  }

  /* ==== Header / nav ==== */
  .primary_header {
    background-color: #0d1117 !important;
    border-bottom: 1px solid #262c33 !important;
  }
  .header_widget .title,
  .header_widget .title a,
  .primary_header .header_buttons a,
  .user_panel_widget a {
    color: #e6edf3 !important;
  }
  /* Logo ships as a pure-black monochrome SVG <img>; invert to white on the dark header */
  .header_logo img,
  .header_logo .full_logo,
  .header_logo .mini { filter: invert(1) !important; }
  /* The narrow-viewport hamburger draws its three bars as div backgrounds filled
     var(--itchio_body_color) (#222) — 1.15:1 on the dark header, i.e. the primary mobile
     nav control is all but invisible. It is a background, so no text/glyph check sees it. */
  .primary_header .mobile_nav_btn .menu_bar { background-color: #c4cdd6 !important; }

  /* Hovering "Log in" / "Register" fills the button itch's light #cfcfd1 — designed to read
     under its red label on the white page, but our accent lands on it at 1.2:1. Every page
     carries these two, and only a hover reaches the state. */
  .user_panel_widget .panel_button:hover {
    background-color: #21262d !important;
    color: #ffa2ad !important;
  }

  .header_dropdown {
    background-color: #161b22 !important;
    border: 1px solid #2d333b !important;
  }
  .header_dropdown a { color: #c4cdd6 !important; }
  .header_dropdown a:hover { background-color: #21262d !important; color: #e6edf3 !important; }
  .header_dropdown .divider { background-color: #2d333b !important; }

  /* Header search field */
  .game_search,
  .search_autocomplete_input_widget {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .game_search input,
  .search_input {
    background-color: transparent !important;
    color: #e6edf3 !important;
  }
  .game_search input::placeholder,
  .search_input::placeholder { color: #8b949e !important; }
  /* Search autocomplete popup: a portal node absent at load (scan-blind), ships pure
     white with #222 rows. Global header chrome — unprefixed so it stays dark on creator
     pages too, where the prefixed heading rule would not reach its .title. */
  /* The popup has border-width 0 — its edge is a box-shadow spread ring (#cdcdcd), so a
     border-color override alone leaves a light hairline framing the dark panel. */
  .autocomplete_results_popup {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: 0 0 0 1px #2d333b, 0 2px 8px rgba(0, 0, 0, 0.5) !important;
  }
  .autocomplete_results_popup .result_header {
    background-color: #161b22 !important;
    color: #8b949e !important;
  }
  .autocomplete_results_popup,
  .autocomplete_results_popup .autocomplete_result,
  .autocomplete_results_popup .tag_results,
  .autocomplete_results_popup .game_results { color: #c4cdd6 !important; }
  .autocomplete_results_popup .autocomplete_result .title { color: #e6edf3 !important; }
  .autocomplete_results_popup .sub_text { color: #8b949e !important; }
  .autocomplete_results_popup .forward_link,
  .autocomplete_results_popup .result_content { color: #fa7d8c !important; }
  .autocomplete_results_popup .autocomplete_result:hover,
  .autocomplete_results_popup .autocomplete_result.selected,
  .autocomplete_results_popup .autocomplete_result.highlighted {
    background-color: #21262d !important;
  }
  .autocomplete_results_popup .result_icon { background-color: #1a1f26 !important; }
  /* The hovered / keyboard-selected row is the <a> INSIDE the li, not the li the
     .autocomplete_result rules above match: itch fills it var(--itchio_light_highlight)
     (#FFF0F0) and rings .selected with a pure-white 3px spread, so the row turns
     near-white under our light title text. Keyboard/hover-gated, so scan-blind. */
  .autocomplete_results_popup li > a:hover,
  .autocomplete_results_popup li > a:focus,
  .autocomplete_results_popup li > a.selected {
    background-color: #21262d !important;
  }
  .autocomplete_results_popup li > a.selected {
    box-shadow: 0 0 0 2px rgba(250, 125, 140, 0.55), 0 0 0 3px #1c2128 !important;
  }
  /* Jam/bundle result state badge in the autocomplete popup (and apex jam listings): the
     "Ended" (state_finished) variant ships a light var(--itchio_gray_back) pill with dark
     text — darken it. The purple default and blue "Upcoming" (state_before) are semantic. */
  .jam_state.state_finished,
  .bundle_state.state_finished {
    background-color: #30363d !important;
    color: #c4cdd6 !important;
  }

  /* Floating action buttons on creator pages (itch chrome; keep opaque-dark) */
  #user_tools .action_btn { background-color: rgba(13, 17, 23, 0.72) !important; color: #e6edf3 !important; }

  /* ==== Content panels / cards / frames ==== */
  /* NB: .bordered is intentionally NOT background-themed — featured game cells use it with
     per-game translucent accent tints derived from cover art; flattening them to grey
     kills the brand colour. Its border is softened by the blanket rule only. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .content_frame,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .stat_box,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .stat_boxes,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .panel,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .grid_column,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_popup,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_options,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .game_info_panel_widget {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Hover-only game-cell details flyout. Its #222 panel is itch's own, but the outer ring of
     its box-shadow is pure white — invisible against itch's white page, a bright halo on ours.
     Hover-gated, so no load-time scan reaches it. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .popup_details_content {
    box-shadow: 0 0 0 2px #0d1117, 0 0 0 4px #2d333b, 0 10px 10px -10px rgba(0, 0, 0, 0.8) !important;
  }
  /* Tab strips (community index, boards) draw their baseline as an inset #dadada shadow,
     not a border — a near-white hairline the border rules cannot reach. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .page_tabs {
    box-shadow: inset 0 -1px 0 0 #2d333b !important;
  }
  /* An open filter group in the browse sidebar flips to .active and paints
     var(--itchio_white_back) (#fff) — recolour the open panel to the elevated surface. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .browse_filter_group_widget.active {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* Filter-row links paint a light grey (#666) hover bar natively — dark elevated instead */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .browse_filter_group_widget a:hover {
    background-color: #21262d !important;
  }
  /* The applied filter's row keeps itch's link-red glyph as its "this filter is on" cue;
     the monochrome-glyph rule below greys it while the star on the neighbouring row (no
     rule) stays accent, so the column reads half-selected. Hand the glyph back to the row. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .browse_filter_group_widget li.active .icon,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .browse_filter_group_widget li.active .svgicon {
    color: inherit !important;
  }
  /* Selected-tag info card in the browse sidebar ships a full white var(--itchio_white_back)
     panel with #434343 body copy — a big white card mid-column on every tag-filtered page. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_tags .filter_tag {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_tags,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_tags .tag_description,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_tags .tag_description p {
    color: #c4cdd6 !important;
  }
  /* Its heading and tag glyph are itch link-red, tuned for the white card — 3.2:1 once dark */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_tags h3 > .text,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_tags h3 > .icon,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_tags h3 > .svgicon {
    color: #fa7d8c !important;
  }
  /* Picker popups (browse "Games" type picker, profile "More" menu): the hovered row ships
     var(--itchio_light_highlight) #FFF0F0, so it flashes near-white under pale link text. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_picker_widget .filter_options .filter_option:hover {
    background-color: #21262d !important;
    color: #ffa2ad !important;
  }
  /* The picker's own closed-state label ships itch's #434343 — dark-on-dark on our chrome
     (the sale-explorer "Sort / Most popular" and "Discount / Any" controls). */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filter_picker_widget .value_label {
    color: #c4cdd6 !important;
  }
  /* Sale-explorer toggle chips ("In bundle", "Staff picks") signal ON purely through a
     #FF2449 border; the blanket reset greys it and on/off become indistinguishable. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .toggle_btn.active {
    border-color: #fa7d8c !important;
  }
  /* The chip is an <a>, so the blanket accent paints its label AND its checkbox glyph the same
     pink whether the filter is on or off — itch writes an OFF chip muted #606060 and an ON one
     body-ink with a red tick, so the border was left carrying the whole state on its own. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .toggle_btn,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .toggle_btn .icon {
    color: #8b949e !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .toggle_btn.active {
    color: #e6edf3 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .toggle_btn.active .icon {
    color: #fa7d8c !important;
  }
  /* Controls-bar divider is a 1px background, not a border, so the border reset misses it */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .control_sep {
    background-color: #2d333b !important;
  }
  /* selectize "Filter with <term>…" affordance ships rgba(48,48,48,.5) — invisible on dark */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .selectize-dropdown .create {
    color: #8b949e !important;
  }
  /* The tag-picker input's own skin paints a near-white gradient as a background-IMAGE plus a
     white inset highlight; both sit on top of the background-color we set, so the "Find tag"
     box on /tags renders as a white plate with our dark placeholder chip inside it. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .selectize-input {
    background-image: none !important;
    box-shadow: none !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .divider {
    background-color: #2d333b !important;
    border-color: #2d333b !important;
  }
  /* Collection thumbnail cells + lazy loaders + "New" badge */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .collection,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .collection_thumb,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .grid_loader,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .grid_header,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .grid_outer,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .grid_column .grid_loader {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .grid_header::before,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .grid_header::after {
    background-color: #1a1f26 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) span.new {
    background-color: #30363d !important;
    color: #e6edf3 !important;
  }
  /* Cover-less game cells fall back to a pure-white .no_cover_text tile with a light
     star glyph — a generated placeholder (not creator art), so darken it. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .no_cover_text {
    background-color: #1a1f26 !important;
    color: #363c44 !important;
  }
  /* Browse layouts (devlogs / bundles / search) + image wrappers behind thumbnails */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .browse_columns,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .browse_sidebar,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .filters_row,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .image_wrapper {
    background-color: #1a1f26 !important;
    border-color: #2d333b !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .browse_columns,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .browse_sidebar { background-color: transparent !important; }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .post_likes,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .post_comments {
    background-color: #30363d !important;
    color: #c4cdd6 !important;
  }
  /* Bundle / sale rows */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .sale_row,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .sale_footer {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .total_price,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .savings,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .summary,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .sub_summary { color: #8b949e !important; }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .summary,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .sale_footer p { color: #c4cdd6 !important; }
  /* Monochrome platform glyphs (icon font uses color, not fill) */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .icon-windows8,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .icon-tux,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .icon-apple,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .icon-android,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .icon-html5,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .icon-globe { color: #8b949e !important; }
  /* Line-art .svgicon glyphs stroke/fill currentColor, which itch leaves at its light-page
     defaults (#434343, and rgba(34,34,34,.7) on the jam-calendar selects). On the dark chrome
     those land at 1.0–1.7:1. Neither scanner sees it: svgWhiteFills only looks for WHITE paint
     and darkOnDark only walks text `color`. Glyphs that already inherit a link or heading
     colour are left alone. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .svgicon.icon_search,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .svgicon.icon_verified,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .svgicon.icon_down_tick2 {
    color: #8b949e !important;
  }
  /* The GitHub mark paints through `fill`, not currentColor, so a `color` rule cannot reach it
     — it needs the fill set directly (monochrome glyph, safe to recolour wholesale). Setting
     `color` here instead would flatten the brand red the button passes down and still not
     repaint the glyph. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .svgicon.icon_github,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .svgicon.icon_github path {
    fill: #8b949e !important;
  }
  /* itch flags a search box holding a query with .is_active and reddens the submit glyph —
