  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .post_tools,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .support_post,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .post_like_button,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .aside_box h3 {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .support_post .post_tag {
    background-color: #30363d !important;
  }
  /* The like widget's frame is a 2px inset box-shadow in itch's raw #FF2449, and its inner
     .button.outline child paints over the left half — so the ring only shows around the
     count. Natively both halves are the same red; our outline-button rule softened the
     child's border and left the ring raw, leaving a saturated box around just the number. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .post_like_button {
    box-shadow: inset 0 0 0 2px rgba(250, 125, 140, 0.45) !important;
  }
  /* "Did you like this post?" ships --itchio_body_color_med (#434343) — 1.6:1 on the card.
     That token also paints the WEB flag's fill, so it is fixed here rather than rebound. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .support_header p {
    color: #c4cdd6 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .likes_count {
    color: #fa7d8c !important;
  }
  /* The header band paints its own white plate through a pseudo, which no element-bg rule reaches */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .blog_post_page .header_column::before {
    background-color: #14181d !important;
  }

  /* ==== Randomizer (itch.io/randomizer) ==== */
  /* Whole page type: the intro card and its rail are var(--itchio_gray_back), and a
     half-white scrim covers the viewport behind them, so the heading and the whole
     explanation render white-on-white. Reached from "Randomizer" in the home rail. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .randomizer_page .sidebar,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .randomizer_intro {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .randomizer_intro_outer {
    background-color: rgba(5, 8, 12, 0.6) !important;
  }
  /* Each filter is a white pill; the .selected one carries a green tint that IS the on-state,
     so darken the base only and leave the tint to stack on the dark pill. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .randomizer_page .filter {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .randomizer_page .filter.selected {
    background-color: #1d3327 !important;
    border-color: #45b976 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .randomizer_page .filter.selected .label {
    color: #c4cdd6 !important;
  }
  /* Once a project is drawn the page swaps to .no_filters: the shell turns #fff behind the
     game frame, the sign-up nudge ships #dadada and the two feedback buttons ship white pills.
     None of it exists until Start is pressed, so a load-time pass sees only the intro. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .randomizer_page {
    background-color: #14181d !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .randomizer_page .login_message,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .randomizer_page .rating_btn {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* ==== Directory (itch.io/directory) ==== */
  /* Another whole page type: the facet grid is a #fff sheet holding dark cards, and each
     section heading sits in its own white band with the "See all …" outline button in it. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .facet_columns,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .content_type > h2,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .content_type .outline_button {
    background-color: #14181d !important;
    border-color: #2d333b !important;
  }

  /* ==== Marketing / index pages (itch.io/app, /developers, /jobs, /game-development/…) ==== */
  /* The app tour alternates full-width text bands: the .right ones ship
     var(--itchio_white_back) while their .left siblings are transparent, so half the copy
     rendered white-on-white. The closing download panel is the same white. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .app_page .image_interstitial {
    background-color: #14181d !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .app_page .download_row {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* The developer page's scroll-in bar is a fixed full-width var(--itchio_white_back) strip
     parked above the viewport at load, so it only exists on screen once the page scrolls —
     and it carries the pure-black monochrome logo, same as the site header. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .developers_page .index_sticky_bar {
    background-color: #0d1117 !important;
    border-color: #2d333b !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .developers_page .sticky_logo {
    filter: invert(1) !important;
  }
  /* Its "Learn more about:" chips are white pills carrying itch's link red — 2.5:1 here */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .developers_page .guide_nav .outline_button {
    background-color: #1c2128 !important;
    border-color: rgba(250, 125, 140, 0.45) !important;
  }
  /* Each section heading leads with an icon-FONT glyph left at itch's #434343 (1.8:1). It is
     drawn by a ::before, so no text-colour walk reads it. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .developers_page .guide h3 .icon {
    color: #8b949e !important;
  }
  /* Job listings are white cards holding itch's link-red titles (2.5:1), and the employer
     logo tile is a light gray_back plate — both while the logo lazy-loads and behind a
     transparent one, plus the briefcase fallback when a listing has no logo at all. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .jobs_browse_page .job_listing_row {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .jobs_browse_page .post_image {
    background-color: #1a1f26 !important;
  }
  /* A single listing is its own page type and the article sheet itself is
     var(--itchio_white_back), so the entire job description rendered white-on-white. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .jobs_view_page {
    background-color: #14181d !important;
  }
  /* Every run of text in a listing card is wrapped in its own <a>, but itch colours only the
     TITLE like a link (#da2c49) and leaves the summary at body ink and the tag chips muted —
     the blanket accent turns the whole card into a wall of pink and the title stops standing
     out. Neither scanner sees it: the native tones are achromatic, and `painted` skips colour. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .job_listing_row p.summary a {
    color: #c4cdd6 !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .job_listing_row .tags a {
    color: #8b949e !important;
  }
  /* Engine directory: each row's sample-project strip is a light gray_back plate, every
     thumbnail in it carries its own white plate behind the (often transparent) cover art,
     and the engine icon sits on the same light tile. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .game_development_tools_page .tool_icon,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .game_development_tools_page .tool_project_preview,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .game_development_tools_page .tool_project_preview img {
    background-color: #1a1f26 !important;
  }

  /* ==== Sale rows / goal bars ==== */
  /* Horizontal thumbnail strips end in a 10px "more to the right" fade whose stop is solid
     white — a bright sliver down the edge of every bundle/sale row. itch ships a dark variant
     of this gradient for its own logged-in dark theme; this is the same remap. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .sale_gradient {
    background-image: linear-gradient(to right, rgba(20, 24, 29, 0), #14181d) !important;
  }
  /* The bundle/sale funding panel is a 50%-white wash: invisible on itch's white page, a large
     light-grey slab here that swallows its own labels. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .goal_progress_widget {
    background-color: #1c2128 !important;
  }
  /* An <img class="game_thumb"> (sale rows, blog post embeds) carries a light gray_back plate
     that shows through transparent art and while the image is still loading. Only the IMG —
     a DIV.game_thumb holds the per-game colour extracted from the cover and is content. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) img.game_thumb,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .cover_image {
    background-color: #1a1f26 !important;
  }

  /* ==== Moderation notices ==== */
  /* "moved this topic to …" ships itch's #606060 straight on the post card (2.6:1) */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .moderation_action,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .moderation_action strong {
    color: #8b949e !important;
  }

  /* ==== Footer ==== */
  .footer .primary,
  .footer .secondary,
  .footer .copyright { color: #8b949e !important; }
  .footer a { color: #a8b0b8 !important; }
  .footer a:hover { color: #e6edf3 !important; }

  /* Horizontal carousel scroll-fade paddles (home rows, profile "Creator of") ship a
     white background-image gradient — a scroll-fade indicator that washes to white over
     cover art. Remap the gradient stops to the page base so it fades to dark. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .paddle_next {
    background-image: linear-gradient(to right, rgba(20, 24, 29, 0) 0%, #14181d 50%, #14181d 100%) !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .paddle_prev {
    background-image: linear-gradient(to right, #14181d 0%, #14181d 50%, rgba(20, 24, 29, 0) 100%) !important;
  }

  /* ==== Home index tab strip (narrow viewports) ==== */
  /* Each tab carries `border-bottom: 4px solid transparent` as a spacer and colours it
     #FF2449 on .active/:hover. The blanket border reset paints all of them grey AND, being
     !important, beats the hover rule — so every tab is underlined and neither cue survives.
     Below itch's breakpoint this strip IS the site nav, so a desktop pass never sees it. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .index_header_tabs > a {
    border-bottom-color: transparent !important;
  }
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .index_header_tabs > a.active,
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .index_header_tabs > a:hover {
    border-bottom-color: #fa7d8c !important;
  }

  /* ==== Large promo / hero sections ==== */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .large_promo_section { background-color: #0d1117 !important; }
  /* The hero's backdrop is the featured game's own blurred cover art, so its lightness varies
     per game and our overlay sits BEHIND it. itch writes this caption white for exactly that
     reason; the blanket accent drops it to ~1.6:1 over a pale cover. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .youtube_link a {
    color: #ffffff !important;
  }
  /* The app banner's "Download app" outline button flips to a solid brand-red fill on hover,
     where itch writes the label white; the blanket accent-hover leaves accent-on-red at 2.3:1. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .app_banner .outline_button:hover {
    color: #ffffff !important;
  }
  /* Featured-game promo panel ships a 30% white overlay -> washed grey on dark; darken it */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .youtube_game_promo_banner_widget {
    background-color: rgba(13, 17, 23, 0.55) !important;
  }
  /* The mobile variant is a position:fixed bottom bar backed by SOLID black, not a translucent
     overlay — its gradient fades to transparent at the right, so a translucent fill here lets
     the grid scroll through it. Must stay opaque. */
  body:not(.game_layout_widget):not(.user_layout_widget):not(.jam_layout_widget) .youtube_mobile_banner_widget {
    background-color: #0d1117 !important;
  }
}
